def make_pieces(g):
    ps=[]
    for comp in components(g):
        cols={g[r][c] for r,c in comp if g[r][c]!=2}
        color=next(iter(cols)) if len(cols)==1 else cols
        ps.append({'color':color,'cells':{(r,c):g[r][c] for r,c in comp},'red':{p for p in comp if g[p[0]][p[1]]==2},'colored':{p for p in comp if g[p[0]][p[1]]!=2}})
    root=next(p for p in ps if p['color']==4)
    return [root]+[p for p in ps if p is not root]

def translated(p,d):
    dr,dc=d
    return {(r+dr,c+dc):v for (r,c),v in p['cells'].items()}

def search(g, maxsol=10000):
    ps=make_pieces(g); n=len(ps); H,W=len(g),len(g[0])
    sols=[]
    # state placements dict index->(dr,dc), occupied colored dict, red positions set per piece via derive
    init={0:(0,0)}
    def rec(place):
        if len(place)==n:
            sols.append(place.copy()); return len(sols)>=maxsol
        # candidates for all unplaced against all placed
        cand=[]
        for j in range(1,n):
            if j in place: continue
            ds=set()
            for i,di in place.items():
                for a in ps[j]['red']:
                    for b in ps[i]['red']:
                        d=(b[0]+di[0]-a[0], b[1]+di[1]-a[1])
                        ds.add((i,j,d))
            for i,j,d in ds:
                cells=translated(ps[j],d)
                if not all(0<=r<H and 0<=c<W for r,c in cells): continue
                # no color-color or color-red collision (red unmatched could be dropped, but conservative)
                ok=True
                for k,dk in place.items():
                    other=translated(ps[k],dk)
                    for p,v in cells.items():
                        if p in other and (v!=2 or other[p]!=2):ok=False;break
                    if not ok:break
                if ok: cand.append((j,d))
        # deterministic
        for j,d in cand:
            place[j]=d
            stop=rec(place)
            del place[j]
            if stop:return True
        return False
    rec(init)
    return ps,sols

def render(g,ps,place):
    H,W=len(g),len(g[0]); allreds=collections.defaultdict(list)
    for i,d in place.items():
        for (r,c),v in translated(ps[i],d).items():
            if v==2:allreds[(r,c)].append(i)
    out=[[0]*W for _ in range(H)]
    for i,d in place.items():
        for (r,c),v in translated(ps[i],d).items():
            if v!=2 or len(allreds[(r,c)])>1 or i==0:out[r][c]=v
    return out

def bbox_area(out):
    pts=[(r,c) for r,row in enumerate(out) for c,v in enumerate(row) if v]
    return (max(r for r,c in pts)-min(r for r,c in pts)+1)*(max(c for r,c in pts)-min(c for r,c in pts)+1)
